/* course18.js — content of Course 18 (Zero Trust and microsegmentation; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 18 — Zero Trust and microsegmentation (why the perimeter is not enough,
   least privilege in rules, microsegmentation, identity verification over 802.1X
   and RADIUS, assuming a breach and blast radius, the journey from a flat network).
   Scene c18Net: NET — FW — SW — segments SRV / HR / IOT / GUEST.
   ============================================================ */
var C18R={net:[60,165],fw:[190,165],sw:[320,165],srv:[470,60],hr:[470,130],iot:[470,200],gst:[470,270]};
function c18Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 320" width="100%" style="display:block">'
    +'<line x1="74" y1="165" x2="176" y2="165" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="204" y1="165" x2="306" y2="165" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="332" y1="157" x2="458" y2="68" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="334" y1="162" x2="456" y2="133" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="334" y1="168" x2="456" y2="197" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="332" y1="173" x2="458" y2="262" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(60,165,'globe','--cyan','NET')
    +csDev(190,165,'firewall','FW')+csDev(320,165,'l3switch','SW')
    +csHost(470,60,'server','--green','SRV')
    +csHost(470,130,'desktop','--blue','HR')
    +csHost(470,200,'iot','--amber','IOT')
    +csHost(470,270,'laptop','--violet','GUEST')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c18P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c18Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c18Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c18g(name,color){var p=C18R[name];return csGlow(p[0],p[1],color,22);}
function c18lbl(tx,c){return '<text x="320" y="22" text-anchor="middle" style="font:700 8px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c18pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.5s')+'" repeatCount="indefinite"/></rect>';}

/* ---------- L1M1 — Castle and moat ---------- */
function renderC18Castle(){return c18P('zta',
  '<b>Before you start:</b> this course builds on basics from the beginner courses (addresses and mask, gateway, VLANs, ports, DNS, firewall) – if any feels unfamiliar, check those first. The classic network security design is nicknamed <b>castle and moat</b>: you build a solid wall at the border (a firewall at the crossing into the internet), and everything <b>inside</b> is treated as trusted. The outer world is dangerous, the internal network is safe. The model has one huge advantage – it is simple – and one fatal weakness: <b>nobody checks anything inside</b>. Whoever gets past the wall moves around the network as if at home. And getting past the wall is fairly easy today: one employee clicking an attachment in a phishing email, one forgotten printer with old firmware, one contractor laptop, one service exposed to the internet. The wall also assumes a clear <b>boundary</b> exists – and it no longer does: people work from home over VPN, data sits in the cloud, phones and IoT devices join the network. The perimeter fell apart into dozens of small entrances. This course is about what to do instead: stop trusting <b>a location in the network</b> and start verifying at <b>every</b> access who the requester is and whether they are entitled. That is called <b>Zero Trust</b>. It is not a product you buy and install – it is a way of designing, which we will assemble piece by piece in this scene.',
  [['castle and moat','the old model: a solid wall at the network border, no checks inside.'],['Zero Trust','a design approach: trust is not derived from network location but verified at every access.']]);}
function mountC18Castle(){c18Mount('zta',[
  {glow:c18g('net','--red')+c18g('fw','--green'),dyn:c18lbl('the wall at the border: outside unsafe, inside safe','--green'),cap:'The <b>castle and moat</b> model: a firewall at the border separates the dangerous internet from the ‘safe’ internal network.'},
  {glow:c18g('hr','--green')+c18g('srv','--green')+c18g('iot','--green')+c18g('gst','--green'),dyn:c18lbl('inside everyone trusts everyone and nothing is checked','--green'),cap:'Inside, everything trusts everything: the computer, the server, the printer and the guest laptop. <b>Nobody checks anything there.</b>'},
  {glow:c18g('net','--red')+c18g('fw','--red')+c18g('sw','--red')+c18g('hr','--red'),dyn:c18pkt('M 60 165 L 190 165 L 320 165 L 470 130','--red')+c18lbl('phishing: the attacker crosses the wall on one click','--red'),cap:'But the wall is easy to cross today: a phishing email, an old printer, a contractor laptop. <b>One</b> entrance is enough.'},
  {glow:c18g('fw','--amber'),dyn:c18lbl('the boundary fell apart: VPN, cloud, phones, IoT','--amber'),cap:'And the boundary is no longer clear either: work from home, cloud, phones, IoT. The perimeter fell apart into dozens of small entrances.'}
]);}
/* ---------- L1M2 — Pivot ---------- */
function renderC18Pivot(){return c18P('ztb',
  'Let us look at what an attacker <b>actually does</b> once inside – you need this scenario in your head, because it is the justification for the whole course. An attacker usually does not start on the most valuable machine. They start where they got in most easily: an employee computer, a camera system, a server in the <b>DMZ</b> (a separate band for services exposed to the internet). From there they <b>pivot</b>: they use the captured machine as a springboard and look around at who that machine can talk to. In a flat network with no internal boundaries the answer is devastating – <b>everything</b>. Then comes <b>lateral movement</b>: the attacker hops from machine to machine, harvests credentials, hunts for weakly protected services and advances toward what they really came for – the database, the backups, the accounting. Notice that this progress <b>has nothing to do with the wall</b>. The border firewall sees only traffic between the inside and the internet; traffic between two machines inside <b>never passes before its eyes at all</b>. That is exactly why Zero Trust starts with a question the classic design never asks: <b>‘and what if the attacker is already inside?’</b> You will see it step by step in the scene – from a captured DMZ server to data it should never have been able to reach.',
  [['pivot','using an already captured machine as a springboard to further targets in the network.'],['lateral movement','the attacker moving sideways, machine to machine, toward more valuable data.'],['DMZ','a separate band for services exposed to the internet; often the first position captured.']]);}
function mountC18Pivot(){c18Mount('ztb',[
  {glow:c18g('net','--red')+c18g('fw','--red')+c18g('sw','--red')+c18g('srv','--red'),dyn:c18pkt('M 60 165 L 190 165 L 320 165 L 470 60','--red')+c18lbl('the attacker takes the DMZ server exposed to the internet','--red'),cap:'The attacker starts where it is easiest – say on the <b>DMZ</b> server that is exposed to the internet.'},
  {glow:c18g('srv','--amber')+c18g('hr','--amber')+c18g('iot','--amber')+c18g('gst','--amber'),dyn:c18lbl('pivot: it looks around at who the captured machine may reach','--amber'),cap:'Then the <b>pivot</b>: the captured machine serves as a springboard. Who may it talk to? In a flat network, everything.'},
  {glow:c18g('srv','--red')+c18g('sw','--red')+c18g('hr','--red'),dyn:c18pkt('M 470 60 L 320 165 L 470 130','--red')+c18lbl('lateral movement: machine to machine, harvesting credentials','--red'),cap:'<b>Lateral movement</b>: the attacker hops machine to machine harvesting credentials – the border firewall never sees this traffic.'},
  {glow:c18g('fw','--muted')+c18g('srv','--red')+c18g('hr','--red')+c18g('iot','--red'),dyn:c18lbl('the wall still stands, yet the attack never touches it','--muted'),cap:'The wall still stands and reports ‘all clear’. So Zero Trust asks: <b>and what if the attacker is already inside?</b>'}
]);}
/* ---------- L1M3 — The three principles ---------- */
function renderC18Principles(){return c18P('ztc',
  'Zero Trust rests on <b>three principles</b>, and they are worth knowing verbatim – the rest of the course is just their translation into concrete settings. <b>1) Verify explicitly.</b> Never assume trust from <b>where</b> someone comes from. A device being in an office socket or on the corporate Wi-Fi is no proof it belongs there. Every access should rest on a verified <b>identity</b> (who it is) and on the state of the device – not on a cable. <b>2) Least privilege.</b> Every account, device and service gets <b>exactly as much access as it needs to work</b> – and nothing more. Not ‘everyone everywhere’, but ‘accounting to the accounting server, the printer nowhere’. This includes privileges not being forever: what stopped being used gets taken away. <b>3) Assume breach.</b> Design the network as though the attacker <b>were</b> already inside. Ask not ‘how to keep them out’, but ‘where do they get from here once they are in’. Microsegmentation, monitoring and fast detection follow from that. Notice how the three hold together: the first decides <b>who</b> may, the second <b>where</b> they may, the third says <b>what happens when it goes wrong anyway</b>. And none of them is bought – all are designed and configured. Soberly put: Zero Trust is the discipline of asking at every connection ‘why is this actually allowed?’.',
  [['verify explicitly','trust is not derived from location; a verified identity and device state decide.'],['least privilege','everyone gets exactly as much access as they need to work – and nothing more.'],['assume breach','design as if the attacker were already inside; ask where they can reach from there.']])
  +courseCTA('ztcTask','Walk the pivot yourself – from a captured DMZ server into the internal network: the task "DMZ must not pivot inside".','Open the task');}
function mountC18Principles(){c18Mount('ztc',[
  {glow:c18g('net','--blue')+c18g('fw','--blue'),dyn:c18pkt('M 60 165 L 190 165','--blue')+c18lbl('principle 1: verify explicitly, not by location','--blue'),cap:'<b>Verify explicitly</b>: a device sitting in an office socket is no proof it belongs. A verified identity decides.'},
  {glow:c18g('sw','--green')+c18g('hr','--green')+c18g('srv','--green'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--green')+c18lbl('principle 2: least privilege – only what work requires','--green'),cap:'<b>Least privilege</b>: accounting to the accounting server yes, the printer nowhere. Exactly the access the work needs.'},
  {glow:c18g('iot','--red')+c18g('gst','--red'),dyn:c18lbl('principle 3: assume breach – where does the attacker reach?','--red'),cap:'<b>Assume breach</b>: ask not ‘how to keep them out’, but ‘where do they get from here once they are in’.'},
  {glow:c18g('fw','--cyan')+c18g('sw','--cyan'),dyn:c18lbl('who may, where they may, and what if it fails anyway','--cyan'),cap:'The three hold together: the first is <b>who</b> may, the second <b>where</b> they may, the third <b>what happens</b> when it fails anyway.'}
]);
  var b=$('ztcTask');if(b)b.onclick=function(){courseTry('dmz-pivot');};
}
/* ---------- L2M1 — From any-any to the specific ---------- */
function renderC18AnyAny(){return c18P('ztd',
  'The least-privilege principle sounds nice, but where is it <b>actually</b> configured in a network? In firewall rules and access lists (ACLs). You know what such a rule looks like and why the list reads top-down from the <b>Network security</b> course. And there, almost every network starts the same way: an <b>any-any</b> rule, meaning ‘from anywhere to anywhere, any port’. It is born of the best intentions – something did not work, so the rule was temporarily widened to get traffic flowing, and it stayed. But any-any <b>is not a rule, it is a disabled check</b>: the firewall stands in the path yet lets everything through. Narrowing it means answering three questions: <b>who</b> (the source – a specific machine or segment, not ‘the whole network’), <b>where</b> (the destination – a specific server, not ‘all servers’) and <b>what</b> (the service and port – say only HTTPS on 443, not ‘everything’). So ‘any-any’ becomes ‘from the office segment to the accounting server, port 443’. The difference in impact is enormous: in the first case a captured employee computer reaches anything, in the second <b>one service on one server</b>. A useful guide when writing rules: start from the <b>service</b>, not the machine. Ask ‘what should this user really do?’ and permit exactly that. And describe your rules – a year later nobody will guess why that exception is there, so nobody will dare delete it.',
  [['any-any','a rule ‘from anywhere to anywhere, any port’ – effectively a disabled check.'],['source, destination, service','the three questions of every rule: who, where and what exactly is allowed.']]);}
function mountC18AnyAny(){c18Mount('ztd',[
  {glow:c18g('fw','--red')+c18g('hr','--red')+c18g('srv','--red')+c18g('iot','--red')+c18g('gst','--red'),dyn:c18lbl('any-any: from anywhere to anywhere, any port','--red'),cap:'An <b>any-any</b> rule lets everything through. The firewall stands in the path, but the check is effectively off.'},
  {glow:c18g('hr','--amber'),dyn:c18lbl('who: a specific segment instead of ‘the whole network’','--amber'),cap:'Narrowing has three steps. <b>Who</b>: the source is a specific machine or segment, not ‘the whole network’.'},
  {glow:c18g('hr','--blue')+c18g('sw','--blue')+c18g('srv','--blue'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--blue')+c18lbl('where: one specific server, not all of them','--blue'),cap:'<b>Where</b>: the destination is one specific server, not ‘all servers’. The rule scope shrinks dramatically.'},
  {glow:c18g('hr','--green')+c18g('sw','--green')+c18g('srv','--green'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--green')+c18lbl('what: only the needed service and port (443)','--green'),cap:'<b>What</b>: permit only the needed service and port – say HTTPS on 443. ‘Any-any’ becomes a concrete, describable rule.'}
]);}
/* ---------- L2M2 — Default deny ---------- */
function renderC18DefaultDeny(){return c18P('zte',
  'Narrowing individual rules is not enough – the <b>default stance</b> also decides, that is what happens to traffic that <b>no</b> rule matches. There are two options and they are two different worlds. <b>Default allow</b>: whatever is not explicitly forbidden gets through. This approach condemns you to an <b>endless list of bans</b> – you would have to enumerate in advance every bad thing anyone will ever invent. Every new service, new port, new attack technique is a hole until someone notices and writes another ban. <b>Default deny</b>: whatever is not explicitly permitted is dropped. The list flips – instead of listing evil you enumerate <b>the few good things</b> that should pass. And since a company network needs surprisingly few things to work, that list is short, understandable and defensible. Default deny is therefore <b>the default stance of Zero Trust</b> and essentially a direct transcription of least privilege into firewall language. A practical note so it does not surprise you: turning default deny on hurts. The first time, something always stops working that nobody knew crossed the network – a silent update, monitoring, a backup agent. So it is done gradually: first the traffic is <b>observed</b>, then what is really needed is permitted, and only at the end the rest is closed. And one more forgotten thing: rules must be <b>cleaned up</b>. When a service ends, its rule stays and quietly holds a door open.',
  [['default deny','whatever is not explicitly permitted is dropped – the default stance of Zero Trust.'],['default allow','whatever is not explicitly forbidden passes; leads to an endless list of bans.'],['rule cleanup','a rule left after a retired service stays and quietly holds a door open.']]);}
function mountC18DefaultDeny(){c18Mount('zte',[
  {glow:c18g('fw','--amber')+c18g('net','--amber'),dyn:c18lbl('default allow: what is not forbidden passes','--amber'),cap:'<b>Default allow</b>: what is not explicitly forbidden passes. You would have to list every bad thing in advance – impossible.'},
  {glow:c18g('fw','--red')+c18g('iot','--red')+c18g('gst','--red'),dyn:c18lbl('every new service is a hole until someone bans it','--red'),cap:'Every new service, port or attack technique is a hole until someone notices and adds a ban.'},
  {glow:c18g('fw','--green'),dyn:c18lbl('default deny: what is not permitted is dropped','--green'),cap:'<b>Default deny</b> flips the list: you enumerate the few good things that should pass. A short, defensible list.'},
  {glow:c18g('hr','--cyan')+c18g('sw','--cyan')+c18g('srv','--cyan'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--cyan')+c18lbl('observe traffic first, then permit, then close the rest','--cyan'),cap:'Turn it on gradually: <b>observe</b> the traffic, permit what is needed, then close the rest. And clean up rules of retired services.'}
]);}
/* ---------- L2M3 — Rules that overlap ---------- */
function renderC18Overlap(){return c18P('ztf',
  'You have default deny and narrowed rules – and yet a hole you do not know about can still creep in. It arises from how a firewall <b>evaluates</b> rules: it walks the list <b>top down</b> and applies the <b>first</b> rule that matches the traffic. It never reads the rest. Hence the first trap: an overly broad rule at the top <b>shadows</b> narrow rules below it. If line one says ‘from the office network to anywhere, permit’ and line ten says ‘from the office network to the accounting server, deny’, that denial is <b>never evaluated</b> – the traffic was decided on line one. The rule looks perfectly fine sitting there and is easily missed in an audit. The second trap is the opposite: a <b>never-used rule</b>. It is either a leftover of a long-retired service or a mistake (a mistyped address, a changed port) – and in both cases it misleads you: you think you protect or permit something while the rule does not apply at all. A practical ordering that works: <b>narrow exceptions</b> at the top (specific denies first, then specific permits), general rules below, and <b>default deny</b> at the very end. Add two habits: describe your rules (who asked, why, until when) and regularly check which ones never match. In the simulator you will feel this on a task where the same traffic matches two rules at once – and the one that is <b>higher</b> decides.',
  [['rule order','the firewall applies the first matching rule from the top; it never reads the rest.'],['shadowing rule','a too-broad rule higher in the list; the narrow rule below it is never evaluated, though it looks valid.']])
  +courseCTA('ztfTask','Build rules from a default deny and permit only what is needed: the task "Default deny".','Open the task');}
function mountC18Overlap(){c18Mount('ztf',[
  {glow:c18g('fw','--blue'),dyn:c18lbl('the firewall reads top down and applies the first match','--blue'),cap:'The firewall walks the rules <b>top down</b> and applies the <b>first</b> that matches. It never reads the rest.'},
  {glow:c18g('hr','--red')+c18g('sw','--red')+c18g('srv','--red')+c18g('iot','--red'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--red')+c18lbl('a broad rule on top shadows the narrow deny below','--red'),cap:'Trap one: a broad ‘from office to anywhere, permit’ on top <b>shadows</b> the narrow deny below. The deny is never evaluated.'},
  {glow:c18g('gst','--amber'),dyn:c18lbl('a never-used rule: a leftover or a typo','--amber'),cap:'Trap two: a <b>never-used rule</b> – a leftover of a retired service or a typo in the address. You think you protect, and it does not apply.'},
  {glow:c18g('fw','--green')+c18g('sw','--green'),dyn:c18lbl('narrow exceptions on top, general below, deny at the end','--green'),cap:'A proven order: <b>narrow exceptions</b> on top, general rules below, <b>default deny</b> at the very end. And describe them.'}
]);
  var b=$('ztfTask');if(b)b.onclick=function(){courseTry('default-deny');};
}
/* ---------- L3M1 — Segment by role ---------- */
function renderC18Roles(){return c18P('ztg',
  'Rules are useless when the network is <b>flat</b> – because then there is nothing to write rules between. So the second half of least privilege is <b>segmentation</b>: splitting the network into smaller units (typically VLANs and subnets) whose traffic must pass a point where it can be checked. And here the first big design mistake happens: segments <b>by floor or room</b>. ‘A VLAN for the second floor, a VLAN for the ground floor’ looks tidy but means nothing for security – on the second floor an accountant, a camera and a printer sit side by side, so inside the segment things that have no business together talk freely. The right guide is: <b>segment by role and sensitivity</b>, not by geography. One segment holds what has <b>the same purpose and the same level of trust</b>: servers apart, user computers apart, IoT and cameras apart, guests apart, the management interface of network devices entirely apart. That is exactly what you see in the scene – four segments hanging off one L3 switch. Once roles are separated, meaningful rules can finally be written: ‘users may reach the application server on 443’, ‘IoT may go nowhere except its data collector’, ‘guests to the internet only’. And when one segment is then captured, the attacker hits a boundary where someone asks where they think they are going. That finer split – down to individual roles and servers, not just ‘inside and DMZ’ – is called <b>microsegmentation</b>.',
  [['segmentation','splitting the network into smaller units whose traffic passes a checked point.'],['microsegmentation','a fine split down to roles and servers, not just inside and DMZ.'],['role over floor','a segment holds what has the same purpose and level of trust.']]);}
function mountC18Roles(){c18Mount('ztg',[
  {glow:c18g('hr','--red')+c18g('srv','--red')+c18g('iot','--red')+c18g('gst','--red'),dyn:c18lbl('a flat network: nothing to write rules between','--red'),cap:'In a <b>flat network</b> there is nothing to write rules between – it is all one unit talking directly.'},
  {glow:c18g('hr','--amber')+c18g('iot','--amber'),dyn:c18lbl('by floor: an accountant next to a camera in one segment','--amber'),cap:'A design mistake: segments <b>by floor</b>. On the second floor an accountant sits next to a camera – security-wise it means nothing.'},
  {glow:c18g('sw','--green')+c18g('srv','--green')+c18g('hr','--blue')+c18g('iot','--amber')+c18g('gst','--violet'),dyn:c18lbl('by role: servers, users, IoT, guests separately','--green'),cap:'The guide: <b>segment by role and sensitivity</b>. Servers apart, users apart, IoT apart, guests apart.'},
  {glow:c18g('hr','--cyan')+c18g('sw','--cyan')+c18g('srv','--cyan'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--cyan')+c18lbl('now meaningful rules between segments are possible','--cyan'),cap:'Only now can meaningful rules be written: users to the application server on 443, IoT nowhere, guests out only.'}
]);}
/* ---------- L3M2 — Guest and IoT ---------- */
function renderC18GuestIot(){return c18P('zth',
  'Two segments hold a special place in practice, because they are where mistakes happen most: <b>guests</b> and <b>IoT</b>. Start with guests. From a security standpoint a guest is a device you <b>know nothing about</b> – not its updates, not its software, not what ran on it yesterday. So a guest may do exactly one thing: <b>go out to the internet</b>. Not to servers, printers, shared drives or <b>management interfaces</b> – and not to other guests either, which can be enforced by client isolation on the Wi-Fi (devices on the same network do not talk to each other). The guest network is a classic case where ‘almost right’ is not enough: a guest who reaches the printer reaches a device whose firmware nobody has updated since delivery. <b>IoT</b> is even more insidious because it does not look dangerous: cameras, sensors, smart bulbs, air conditioning, printers. What they share is a <b>weak or nonexistent way to secure them</b>: default passwords, outdated firmware, no updates, no antivirus. At the same time they are on the network <b>permanently</b> and nobody watches them. That is an ideal springboard for an attacker – quiet, forgotten, and yet inside. The rule for IoT is therefore: its own segment, out only to what it truly needs (typically one data collector or one vendor service), and <b>no access to the rest of the network</b>. And since a camera has no reason to talk to another camera, isolation inside the segment fits here too. The question to keep asking about both segments: <b>what happens when an attacker takes exactly this device?</b>',
  [['guest network','a guest may reach only the internet; not servers, printers, management or other guests.'],['client isolation','devices on the same network do not talk to each other, even on the same Wi-Fi.'],['IoT','devices that can hardly be secured; their own segment and out only to what is needed.']]);}
function mountC18GuestIot(){c18Mount('zth',[
  {glow:c18g('gst','--violet')+c18g('sw','--violet')+c18g('fw','--violet')+c18g('net','--violet'),dyn:c18pkt('M 470 270 L 320 165 L 190 165 L 60 165','--violet')+c18lbl('a guest may do exactly one thing: out to the internet','--violet'),cap:'A guest is a device you <b>know nothing about</b>. It may do exactly one thing: go out to the internet.'},
  {glow:c18g('gst','--red')+c18g('srv','--red')+c18g('iot','--red'),dyn:c18lbl('not to servers, printers, management or other guests','--red'),cap:'Not to servers, printers, shared drives or <b>management interfaces</b> – nor to other guests (client isolation).'},
  {glow:c18g('iot','--amber'),dyn:c18lbl('IoT: default passwords, old firmware, nobody watches','--amber'),cap:'<b>IoT</b> does not look dangerous, yet it has default passwords and old firmware – and is on the network permanently. An ideal springboard.'},
  {glow:c18g('iot','--green')+c18g('sw','--green')+c18g('srv','--green'),dyn:c18pkt('M 470 200 L 320 165 L 470 60','--green')+c18lbl('IoT: its own segment and out only to one collector','--green'),cap:'The IoT rule: its own segment, out only to what is needed (one collector) and <b>no access to the rest of the network</b>.'}
]);}
/* ---------- L3M3 — How many segments is too many ---------- */
function renderC18HowMany(){return c18P('zti',
  'If segmentation is so useful, why not put every machine in its own segment? Because segmentation has a <b>cost</b>, and it grows faster than you would expect. Each further segment means another subnet, another interface on the L3 device, another set of rules – and above all more <b>intersections</b>: the more segments, the more pairs for which someone must decide what may pass. The practical outcome is always the same: a request comes in, nobody dares to decide, so more is permitted just in case – and within a year the fine split turns into a finely sliced flat network where everything may reach everything. That is the worst of both worlds: the complexity of microsegmentation without its benefit. A sensible level comes from <b>two questions</b>. First: <b>does the level of trust differ?</b> A camera and an accounting server, yes – they belong apart. Two accounting computers, no – they belong together. Second: <b>can I write a rule for that boundary that I can defend?</b> When nobody can answer ‘what exactly should cross here?’, the boundary does not belong there yet. A good approach is to start <b>coarse</b> (servers, users, IoT, guests, management) and split further <b>only where it hurts</b> – typically around the most sensitive data. Segmentation is not a contest for the number of VLANs; it is a tool to shrink the attacker’s reach to a size you can still administer.',
  [['the cost of segmentation','each segment adds a subnet, an interface and above all more pairs to decide between.'],['two questions','does the trust level differ? And can I write a defensible rule for that boundary?']])
  +courseCTA('ztiTask','Design the split of a network into role-based segments: the task "VLAN design".','Open the task');}
function mountC18HowMany(){c18Mount('zti',[
  {glow:c18g('sw','--green')+c18g('srv','--green')+c18g('hr','--green')+c18g('iot','--green')+c18g('gst','--green'),dyn:c18lbl('coarse split: servers, users, IoT, guests, management','--green'),cap:'Start <b>coarse</b>: servers, users, IoT, guests and management. That covers most real differences in trust.'},
  {glow:c18g('sw','--amber'),dyn:c18lbl('each further segment adds pairs to decide about','--amber'),cap:'Each further segment adds a subnet, an interface and above all <b>intersections</b> – pairs where someone must decide what may pass.'},
  {glow:c18g('hr','--red')+c18g('iot','--red')+c18g('gst','--red')+c18g('srv','--red'),dyn:c18lbl('nobody dares to decide, so more gets permitted','--red'),cap:'When the split is too fine, nobody dares decide and more is permitted. The result is a <b>finely sliced flat network</b>.'},
  {glow:c18g('srv','--cyan')+c18g('sw','--cyan')+c18g('hr','--cyan'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--cyan')+c18lbl('split further only where trust differs and a rule holds','--cyan'),cap:'Two questions: <b>does the trust level differ?</b> And <b>can I write a defensible rule for that boundary?</b> Otherwise it does not belong there.'}
]);
  var b=$('ztiTask');if(b)b.onclick=function(){courseTry('vlan-design');};
}
/* ---------- L4M1 — 802.1X and RADIUS ---------- */
function renderC18Dot1x(){return c18P('ztj',
  'Back to the first principle: <b>verify explicitly</b>. In a classic network the ‘verification’ is a physical socket or knowing the Wi-Fi password – but a socket identifies nobody, and the shared Wi-Fi password (WPA2-Personal) is known to half the company, to former employees and to everyone it was ever forwarded to. Whoever connects gets the network. That is exactly what Zero Trust rejects. The answer is <b>802.1X</b>: a standard where the device or user <b>logs in</b> before the port or Wi-Fi lets them onto the network at all. Three roles play in it. The <b>client</b> (your laptop) presents credentials or a certificate. The <b>authenticator</b> (the switch or access point) does not verify them itself – it just holds the door shut and passes them on. The <b>authentication server</b>, typically <b>RADIUS</b>, decides yes/no and sends the answer back. Only after a ‘yes’ does the port open. On Wi-Fi this is called <b>WPA2/WPA3-Enterprise</b> – instead of one shared password <b>everyone has their own</b> login (the <b>Wi-Fi: security in depth</b> course covers this in detail). Two practical consequences that make it worth the work: first, an <b>employee leaving</b> means revoking one account, not changing the password for the whole company; second, RADIUS can return not just yes/no but also <b>which segment</b> the device belongs to – so lessons 3 and 4 connect here: identity decides the placement, not the socket.',
  [['802.1X','verifying a device or user before the port or Wi-Fi admits them to the network.'],['RADIUS','the authentication server that decides yes/no and can also return the target segment.'],['WPA2/WPA3-Enterprise','Wi-Fi where everyone has their own login instead of one shared password.']]);}
function mountC18Dot1x(){c18Mount('ztj',[
  {glow:c18g('gst','--red')+c18g('sw','--red'),dyn:c18lbl('the shared Wi-Fi password is known to half the company','--red'),cap:'A shared Wi-Fi password or a socket <b>identifies</b> nobody. Whoever connects gets the network – Zero Trust rejects that.'},
  {glow:c18g('hr','--blue')+c18g('sw','--blue'),dyn:c18pkt('M 470 130 L 320 165','--blue')+c18lbl('the client presents a login, the authenticator waits','--blue'),cap:'<b>802.1X</b>: the client presents credentials or a certificate. The switch or access point does not verify them – it holds the door shut.'},
  {glow:c18g('sw','--cyan')+c18g('srv','--cyan'),dyn:c18pkt('M 320 165 L 470 60','--cyan')+c18lbl('the RADIUS authentication server decides yes or no','--cyan'),cap:'The credentials travel to the <b>authentication server</b> (RADIUS). It decides yes/no and sends the answer back to the switch.'},
  {glow:c18g('hr','--green')+c18g('sw','--green'),dyn:c18pkt('M 320 165 L 470 130','--green')+c18lbl('after ‘yes’ the port opens – and RADIUS returns a segment','--green'),cap:'Only after ‘yes’ does the port open. RADIUS can also return <b>which segment</b> the device belongs to – identity decides the placement.'}
]);}
/* ---------- L4M2 — VPN against RADIUS ---------- */
function renderC18VpnRadius(){return c18P('ztk',
  'The same logic applies to remote access. A <b>VPN</b> creates an encrypted tunnel from home or a hotel into the company network – and that is exactly why it is an extremely sensitive place: whoever passes the VPN ends up <b>inside</b>, precisely where the classic model stops checking. If the VPN verified only against a shared password or a local account on one box, you end up like with the shared Wi-Fi. So a VPN is typically <b>wired to the same RADIUS</b> as Wi-Fi and the ports: the user logs in with their company account, the VPN passes the query to the authentication server, and it decides. The benefit is organizational, not technical: <b>one identity for all entrances</b>. Block the account and the person gets in neither over Wi-Fi, nor over VPN, nor over a cable. One more thing must not be forgotten with remote access: <b>multi-factor authentication</b> (MFA) – a second proof on top of the password (a code from the phone, a hardware key). A stolen password alone is then not enough, and stolen passwords are the most common way in. And beware of the mistake Zero Trust explicitly holds against the classic design: <b>a VPN by itself is not Zero Trust</b>. When the tunnel delivers the user into a flat internal network where they may reach everything, you have merely extended the attacker’s cable into their living room. A VPN should end in a <b>segment with rules</b> – a remote user should have privileges just as narrow as in the office, not wider.',
  [['VPN','an encrypted tunnel into the company network; it must end in a segment with rules, not a flat network.'],['MFA','multi-factor authentication: a second proof beyond the password, so a stolen one is not enough.'],['one identity','Wi-Fi, ports and VPN all ask the same server; a blocked account loses every entrance.']]);}
function mountC18VpnRadius(){c18Mount('ztk',[
  {glow:c18g('net','--blue')+c18g('fw','--blue'),dyn:c18pkt('M 60 165 L 190 165','--blue')+c18lbl('VPN: an encrypted tunnel from home into the network','--blue'),cap:'A <b>VPN</b> makes an encrypted tunnel inside. Whoever passes it ends up inside – hence an extremely sensitive place.'},
  {glow:c18g('fw','--cyan')+c18g('sw','--cyan')+c18g('srv','--cyan'),dyn:c18pkt('M 190 165 L 320 165 L 470 60','--cyan')+c18lbl('the VPN asks the same RADIUS as Wi-Fi and ports','--cyan'),cap:'The VPN asks <b>the same authentication server</b> as Wi-Fi and the ports: one identity for every entrance.'},
  {glow:c18g('net','--green')+c18g('fw','--green'),dyn:c18lbl('MFA: a stolen password alone is not enough','--green'),cap:'Plus <b>MFA</b>: a second proof beyond the password. A stolen password alone then fails – and that is the most common way in.'},
  {glow:c18g('fw','--red')+c18g('sw','--red')+c18g('hr','--red')+c18g('srv','--red')+c18g('iot','--red'),dyn:c18pkt('M 190 165 L 320 165 L 470 200','--red')+c18lbl('VPN into a flat network = an extended attacker cable','--red'),cap:'Beware: <b>a VPN alone is not Zero Trust</b>. If the tunnel ends in a flat network you only extended the attacker’s cable. It must end in a segment with rules.'}
]);}
/* ---------- L4M3 — When the authentication server fails ---------- */
function renderC18RadiusDown(){return c18P('ztl',
  'When one authentication server decides every entrance to the network, you have raised a new question: <b>what happens when it fails?</b> The answer is unpleasant – without it nobody gets in. Wi-Fi rejects employees, ports stay shut, the VPN refuses logins. A security device has become a <b>single point of failure</b> for the whole company. The fix has two parts. The first is obvious: <b>double</b> the authentication server and configure both addresses on the devices (primary and backup) so they ask the second one on failure. The same resilience principle you know from the course <i>Network resilience and scaling</i> – just applied to a security service, where it is easily forgotten. The second part is a decision you must make <b>deliberately in advance</b>: how should the network behave when <b>even the second one</b> is unreachable? You have two options and both cost something. <b>Fail-closed</b>: nobody gets in. Safe, but it means a blanket outage – and in operations that must not stop, the damage may exceed the risk. <b>Fail-open</b>: let them in without verification. Work continues, but at exactly that moment you have a network <b>with no identity check</b> – a state an attacker finds worth causing. The compromise most often chosen in practice is to admit devices into a <b>heavily restricted segment</b>: they get connectivity to the bare essentials, but no access to sensitive data. A sober conclusion: security that cannot be operated gets switched off sooner or later. Resilience of authentication is therefore part of its design, not an afterthought.',
  [['fail-closed','with authentication unreachable nobody gets in: safe, but a blanket outage.'],['fail-open','with authentication unreachable access is granted unverified: work continues, identity checks are gone.'],['backup server','a second authentication server and both addresses on devices; otherwise it is a single point of failure.']])
  +courseCTA('ztlTask','Build Wi-Fi with a per-person login against an authentication server: the task "Wi-Fi Enterprise".','Open the task');}
function mountC18RadiusDown(){c18Mount('ztl',[
  {glow:c18g('srv','--red'),dyn:c18lbl('the authentication server failed – nobody gets in','--red'),cap:'When the authentication server fails, nobody gets in: Wi-Fi, ports or VPN. A security device became a <b>single point of failure</b>.'},
  {glow:c18g('srv','--green')+c18g('sw','--green'),dyn:c18pkt('M 320 165 L 470 60','--green')+c18lbl('double the server and set both addresses on devices','--green'),cap:'Part one of the fix: <b>double</b> the server and give devices a primary and a backup address – resilience as in the course <i>Network resilience and scaling</i>.'},
  {glow:c18g('sw','--amber')+c18g('hr','--amber')+c18g('gst','--amber'),dyn:c18lbl('fail-closed shuts all out, fail-open admits unverified','--amber'),cap:'Decide in advance: <b>fail-closed</b> (nobody in, blanket outage) or <b>fail-open</b> (admits unverified, a network with no identity check).'},
  {glow:c18g('hr','--cyan')+c18g('sw','--cyan'),dyn:c18pkt('M 470 130 L 320 165','--cyan')+c18lbl('the compromise: admit to a heavily restricted segment','--cyan'),cap:'The usual compromise: admit devices to a <b>heavily restricted segment</b> – essential connectivity, no sensitive data.'}
]);
  var b=$('ztlTask');if(b)b.onclick=function(){courseTry('wifi-enterprise');};
}
/* ---------- L5M1 — Blast radius ---------- */
function renderC18Blast(){return c18P('ztm',
  'The third principle – <b>assume breach</b> – has one very practical tool: the question <b>‘where does the attacker reach from here?’</b>. The answer is called the <b>blast radius</b>: the set of everything reachable from one captured device. It is the best way to measure whether your segmentation is actually worth anything, because it does not ask ‘are we safe?’ (nobody can answer that) but ‘what specifically falls when this falls?’. The procedure is boring and effective: take a device – ideally the most vulnerable one, a camera, a printer, a guest laptop – and list everything it can open a connection to. Then repeat it for the DMZ server and for an ordinary employee computer. In a flat network the answer comes out the same every time: <b>everything</b>. In a well-split network you get three <b>small and different</b> lists – and that is the whole point. Segmentation cannot prevent the first breach (it arrives by phishing or a vulnerability; the network cannot stop that), but it decides whether it becomes an incident on one machine or on the whole company. This way of thinking also <b>reverses the order</b> of work: you do not start from what you want to permit, but from what you cannot afford to lose – and from there you ask who can reach it today. The most valuable data should have the smallest blast radius; when it turns out a hallway camera can reach the accounting server, you have just found your next task.',
  [['blast radius','the reach of damage: everything reachable from one captured device.'],['reversed order','do not start from what to permit, but from what you cannot afford to lose.']]);}
function mountC18Blast(){c18Mount('ztm',[
  {glow:c18g('iot','--amber'),dyn:c18lbl('take the most vulnerable device: a hallway camera','--amber'),cap:'Take the most vulnerable device – a camera, a printer, a guest laptop – and ask: <b>where does the attacker reach from here?</b>'},
  {glow:c18g('iot','--red')+c18g('sw','--red')+c18g('hr','--red')+c18g('srv','--red')+c18g('gst','--red'),dyn:c18pkt('M 470 200 L 320 165 L 470 60','--red')+c18lbl('a flat network: the answer is always ‘everything’','--red'),cap:'In a flat network the answer is always the same: <b>everything</b>. That is the maximum <b>blast radius</b>.'},
  {glow:c18g('iot','--green')+c18g('sw','--green'),dyn:c18pkt('M 470 200 L 320 165','--green')+c18lbl('a split network: a short list, the attack stops','--green'),cap:'In a split network the list is <b>short</b>: the camera reaches its collector and nothing else. It will not prevent the breach, but it shrinks the damage.'},
  {glow:c18g('srv','--cyan'),dyn:c18lbl('the most valuable data needs the smallest blast radius','--cyan'),cap:'Reverse the order: start from what you <b>cannot afford to lose</b> and ask who can reach it today.'}
]);}
/* ---------- L5M2 — Decoy (honeypot) ---------- */
function renderC18Honeypot(){return c18P('ztn',
  'Assuming breach has a second half: when the attacker <b>is</b> inside, you want to find out <b>early</b>. That is hard in practice, because a normal network is noisy – logs run to hundreds of thousands of lines and the attacker hides in them. But there is one strikingly simple trick: a <b>decoy</b> (honeypot). You place a device or service in the network that looks tempting – a server named something like ‘backups’ or ‘accounting’ – but which in reality <b>has no legitimate purpose</b>. No person and no application has any reason to connect to it. And that is precisely its strength: <b>any</b> connection attempt is suspicious. You need not distinguish normal from unusual behavior, you need not tune thresholds – zero is a clear line. Whoever touches the decoy is either looking around the network (an attacker) or misconfigured something (also worth knowing). A decoy is therefore a tool of <b>early warning</b>, not of defense: it stops nobody, but it tells you something is happening while you can still do something about it. Two practical notes. First: the decoy must be <b>isolated</b> and must hold nothing valuable – otherwise you added one more weak machine and helped the attacker. Second: it is pointless if nobody looks at its alerts. That holds generally – <b>monitoring without response is just collecting data</b>. Zero Trust does not end at configuring rules; it expects something to get through, and wants to <b>see</b> it.',
  [['decoy (honeypot)','a tempting device with no legitimate purpose; any access to it is suspicious.'],['early warning','a decoy stops nobody, but tells you something is happening while you can still act.']]);}
function mountC18Honeypot(){c18Mount('ztn',[
  {glow:c18g('srv','--muted')+c18g('hr','--muted')+c18g('iot','--muted'),dyn:c18lbl('a normal network is noisy, the attacker hides in logs','--muted'),cap:'You want to learn of a breach <b>early</b>, but a normal network is noisy and the attacker hides in the records.'},
  {glow:c18g('srv','--violet'),dyn:c18lbl('a decoy: a tempting server with no legitimate purpose','--violet'),cap:'A <b>decoy</b> (honeypot): a device that looks tempting but has no legitimate purpose. Nobody has a reason to visit it.'},
  {glow:c18g('iot','--red')+c18g('sw','--red')+c18g('srv','--red'),dyn:c18pkt('M 470 200 L 320 165 L 470 60','--red')+c18lbl('any access to the decoy is suspicious right away','--red'),cap:'So <b>any</b> connection attempt is suspicious. No thresholds to tune – zero accesses is a clear line.'},
  {glow:c18g('srv','--cyan')+c18g('sw','--cyan'),dyn:c18lbl('decoy isolated, holding nothing valuable – and watched','--cyan'),cap:'Two conditions: the decoy must be <b>isolated and hold nothing valuable</b> – and someone must watch. Monitoring without response is just collecting data.'}
]);}
/* ---------- L5M3 — The topology check as hygiene ---------- */
function renderC18Hygiene(){return c18P('zto',
  'A Zero Trust design has an unpleasant property: <b>it decays on its own</b>. Not because it is bad, but because the network lives. A project arrives and with it an exception ‘just temporarily’. A colleague leaves and their rules stay. Someone plugs a device into a socket that happens not to verify. A contractor gets access to one server and nobody removes it when the contract ends. Every single change looks harmless; after two years the careful design is again a flat network with a wall around it. Only one thing helps: <b>regular hygiene</b> – a repeated check, not a one-off project. In the simulator you have the <b>topology check</b> for this: it walks your network and flags weak spots that are easy to miss – a segment with no rules, a device that reaches where it should not, a guest network wired inside. Treat it as practice for what you do in a real network by hand or with a tool: walk the <b>rule list</b> (what never matched? what has no reason to exist?), walk the <b>access list</b> (who holds a privilege they do not use?) and walk the <b>segment boundaries</b> (what exactly crosses here and why?). A useful rhythm is simple: after every larger change, and then regularly even when nothing changed – those ‘unchanged’ periods are usually when the most exceptions piled up. Zero Trust is not a state you reach; it is <b>maintenance</b>.',
  [['design hygiene','a repeated review of rules, privileges and segment boundaries, not a one-off project.'],['topology check','a simulator tool: it walks the network and flags weak spots that are easy to miss.']])
  +courseCTA('ztoTask','Check where a guest and IoT really reach: the task "Guest isolation".','Open the task');}
function mountC18Hygiene(){c18Mount('zto',[
  {glow:c18g('fw','--amber')+c18g('hr','--amber'),dyn:c18lbl('an exception ‘just temporarily’ and a leaver’s rules','--amber'),cap:'The design <b>decays on its own</b>: an exception ‘just temporarily’, a leaver’s rules, a contractor’s access after the contract.'},
  {glow:c18g('hr','--red')+c18g('srv','--red')+c18g('iot','--red')+c18g('gst','--red'),dyn:c18lbl('after two years the design is a flat network again','--red'),cap:'Every change looks harmless, yet after two years the careful design is <b>a flat network again</b> with a wall around it.'},
  {glow:c18g('sw','--cyan')+c18g('gst','--cyan'),dyn:c18pkt('M 470 270 L 320 165','--cyan')+c18lbl('the topology check finds a segment with no rules','--cyan'),cap:'The <b>topology check</b> helps: it walks the network and shows weak spots – a segment with no rules or a guest network wired inside.'},
  {glow:c18g('fw','--green')+c18g('sw','--green'),dyn:c18lbl('walk the rules, the privileges and the boundaries','--green'),cap:'The rhythm: after every larger change, then regularly, walk the <b>rules, privileges and segment boundaries</b>. Zero Trust is maintenance, not a state.'}
]);
  var b=$('ztoTask');if(b)b.onclick=function(){courseTry('guest-iso');};
}
/* ---------- L6M1 — The journey from a flat network ---------- */
function renderC18Journey(){return c18P('ztp',
  'The last lesson is practical: you have a flat network and want Zero Trust out of it. Where to start so you do not stall after a week? A proven <b>order of steps</b> looks like this. <b>1) Find out what is actually in the network.</b> You cannot protect what you do not know about – and every network holds a device nobody expected. <b>2) Find out what talks to what.</b> Just <b>observe the traffic</b> for a while. Without it you write rules blindly and the first default deny takes the company down. <b>3) Separate the most sensitive and the most risky.</b> Coarse segments: servers, users, IoT, guests, management. The biggest benefit for the least work. <b>4) Write rules between segments</b>, permissive for now and even broad, but <b>named</b> – so it is visible what should cross. <b>5) Switch to default deny</b>, segment by segment, not everywhere at once. Start where the traffic is best described – typically guests and IoT. <b>6) Add identity verification</b>: 802.1X on ports and Wi-Fi, VPN and MFA against the same authentication server. <b>7) Build monitoring and rehearse the response.</b> Finally <b>8) repeat</b> – reviewing rules and privileges is regular work. Notice that the first five steps <b>need no new product</b>: they are done with the rules and segments you already have. And notice where identity verification sits: sixth, because without segments and rules it has nothing to enforce. The most common mistake is to start from the end – buy a tool and hope it decides for you what should be allowed.',
  [['order of steps','inventory → observe traffic → segment → rules → default deny → identity → monitoring → repeat.'],['observe before you deny','without knowing the real traffic, the first default deny takes the company down.']]);}
function mountC18Journey(){c18Mount('ztp',[
  {glow:c18g('sw','--blue')+c18g('hr','--blue')+c18g('iot','--blue')+c18g('gst','--blue')+c18g('srv','--blue'),dyn:c18lbl('steps 1 and 2: find what is there and what talks','--blue'),cap:'Steps 1 and 2: <b>find out what is in the network</b> and just <b>observe the traffic</b> for a while. Otherwise you write rules blindly.'},
  {glow:c18g('srv','--green')+c18g('hr','--green')+c18g('iot','--amber')+c18g('gst','--violet'),dyn:c18lbl('steps 3 and 4: coarse segments and named rules','--green'),cap:'Steps 3 and 4: <b>coarse segments</b> (servers, users, IoT, guests, management) and named rules between them.'},
  {glow:c18g('fw','--red')+c18g('gst','--red')+c18g('iot','--red'),dyn:c18lbl('step 5: default deny, segment by segment','--red'),cap:'Step 5: switch to <b>default deny</b> segment by segment – start where traffic is best described (guests, IoT).'},
  {glow:c18g('sw','--cyan')+c18g('srv','--cyan')+c18g('hr','--cyan'),dyn:c18pkt('M 470 130 L 320 165 L 470 60','--cyan')+c18lbl('steps 6 to 8: identity, monitoring, then repeat','--cyan'),cap:'Steps 6 to 8: <b>identity verification</b> (802.1X, VPN, MFA), <b>monitoring</b>, then repeat. The first five steps need no new product.'}
]);}
/* ---------- L6M2 — What Zero Trust is not ---------- */
function renderC18NotZt(){return c18P('ztq',
  'There is a lot of marketing around Zero Trust, so let us be clear about what Zero Trust <b>is not</b> – it will save you money and disappointment. <b>It is not a product.</b> There is no box or license after whose deployment you have Zero Trust. It is a way of designing, assembled from things you already know: segmentation, least-privilege rules, identity verification, monitoring. Tools will help, but nobody makes the ‘who may go where’ decision for you. <b>It is not just a VPN.</b> A VPN solves <b>encrypted transport</b> and entry from outside – it does not solve what you may do once inside. When the tunnel ends in a flat network, it is castle and moat with a longer moat. <b>It is not just MFA.</b> A strong login is excellent and saves a lot of trouble, but it is only the first of three principles; after logging in, where the network lets you still applies. <b>It is not ‘distrusting people’.</b> The name misleads – it is not about suspecting employees, but about trust <b>not being derived from location</b> and not being granted permanently. <b>It is not a one-off project</b>, as you saw with hygiene. And finally: <b>it is not all or nothing</b>. Separating guests and IoT and closing a few needless paths is an enormous gain even if you have no 802.1X and never will. Soberly: Zero Trust is a direction the network moves in step by step – and every step counts on its own.',
  [['not a product','a way of designing from known parts: segments, rules, identity, monitoring.'],['not just a VPN','a VPN solves transport and entry, not what you may do once inside.'],['not all or nothing','separating guests and IoT is a big gain even without 802.1X; every step counts.']]);}
function mountC18NotZt(){c18Mount('ztq',[
  {glow:c18g('fw','--muted')+c18g('sw','--muted'),dyn:c18lbl('no box installs Zero Trust for you','--muted'),cap:'<b>Not a product</b>: there is no box whose deployment gives you Zero Trust. Nobody makes the ‘who may go where’ decision for you.'},
  {glow:c18g('net','--amber')+c18g('fw','--amber')+c18g('sw','--amber')+c18g('hr','--amber'),dyn:c18pkt('M 60 165 L 190 165 L 320 165','--amber')+c18lbl('a VPN solves entry, not what you may do inside','--amber'),cap:'<b>Not just a VPN</b>: the tunnel solves encrypted transport and entry. Ending in a flat network, it is castle and moat with a longer moat.'},
  {glow:c18g('hr','--blue'),dyn:c18lbl('MFA is only the first of three principles, not all','--blue'),cap:'<b>Not just MFA</b>: a strong login is the first of three principles. After logging in, where the network lets you still applies.'},
  {glow:c18g('gst','--green')+c18g('iot','--green'),dyn:c18lbl('separating guests and IoT counts even without tools','--green'),cap:'<b>Not all or nothing</b>: separating guests and IoT is a big gain even without 802.1X. Every step counts on its own.'}
]);}
/* ---------- L6M3 — Checklist ---------- */
function renderC18Checklist(){return c18P('ztr',
  'To close, a <b>checklist</b> you can take to any network design or review. <b>Identity:</b> Is every entrance (cable, Wi-Fi, VPN) verified against one identity source? Does remote access have MFA? Are privileges removed when a person leaves or a contract ends? <b>Segments:</b> Are they split by role and sensitivity, not by floor? Do guests, IoT and management interfaces have their own segment? Is the guest network really internet-only? <b>Rules:</b> Is default deny in effect? Is every rule narrow (source, destination, service) and described? Does a broad rule on top shadow narrow ones below? Are there rules that never matched? <b>Reach:</b> If I captured a camera, a guest laptop or the DMZ server, where would I get from there? Do the most valuable data have the smallest blast radius? <b>Operation and resilience:</b> Has the authentication server become the one box the whole company hangs on? Do I know what happens when it fails? Does anyone look at the alerts? Have I ever rehearsed the response? A final piece of advice to take away: <b>pick the one answer that hurt most today and fix it.</b> Zero Trust is not done at once – it is done by making that list one missing boundary shorter next time. Congratulations on finishing the course; now try it in the simulator on the challenge where a guest is wired where they should not be.',
  [['the checklist','identity, segments, rules, blast radius, operation and resilience – five areas of questions.'],['one fix','pick the answer that hurt most and fix it; Zero Trust is done step by step.']])
  +courseCTA('ztrTask','Test it on a challenge: a guest is wired where they should not be – find it and fix it: "Challenge: guest on the network".','Open the challenge');}
function mountC18Checklist(){c18Mount('ztr',[
  {glow:c18g('net','--blue')+c18g('sw','--blue')+c18g('hr','--blue'),dyn:c18lbl('identity: one source for cable, Wi-Fi and VPN, plus MFA','--blue'),cap:'<b>Identity</b>: is every entrance verified against one source? Does remote access have MFA? Are privileges removed on departure?'},
  {glow:c18g('srv','--green')+c18g('iot','--amber')+c18g('gst','--violet'),dyn:c18lbl('segments: roles over floors, guests and IoT apart','--green'),cap:'<b>Segments</b>: split by role and sensitivity? Do guests, IoT and management have their own? Is the guest network really internet-only?'},
  {glow:c18g('fw','--cyan'),dyn:c18lbl('rules: default deny, narrow, described, unshadowed','--cyan'),cap:'<b>Rules</b>: is default deny in effect? Is each one narrow (source, destination, service) and described? Does a broad rule shadow the narrow ones?'},
  {glow:c18g('iot','--red')+c18g('sw','--red')+c18g('srv','--red'),dyn:c18pkt('M 470 200 L 320 165 L 470 60','--red')+c18lbl('reach and operation: what falls with this, and who watches','--red'),cap:'<b>Reach and operation</b>: where do I get from a captured camera? What if authentication fails? Does anyone watch the alerts? Pick one answer and fix it.'}
]);
  var b=$('ztrTask');if(b)b.onclick=function(){courseTry('ch-guest');};
}

